const presets={sma:{icon:'∿',left:'SMA 50',op:'cruza por encima',right:'SMA 200',value:'50 / 200'},ema:{icon:'∿',left:'EMA',op:'cruza por encima',right:'EMA',value:'20 / 50'},rsi:{icon:'≋',left:'RSI',op:'es menor que',right:'Valor',value:'30'},macd:{icon:'⌁',left:'MACD',op:'cruza por encima',right:'Señal',value:'9'},cross:{icon:'↗',left:'SMA 50',op:'cruza por encima',right:'SMA 200',value:'cierre'},greater:{icon:'›',left:'Precio',op:'es mayor que',right:'SMA',value:'200'},stop:{icon:'◇',left:'Pérdida',op:'alcanza',right:'Porcentaje',value:'2'},take:{icon:'◎',left:'Ganancia',op:'alcanza',right:'Porcentaje',value:'5'}};
let state={entry:[{...presets.cross},{...presets.rsi}],exit:[{...presets.cross,op:'cruza por debajo'},{...presets.stop},{...presets.take}]};
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],esc=s=>String(s).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
function ruleTemplate(r,side,i){return `<div class="rule" data-side="${side}" data-index="${i}"><span class="rule-icon">${r.icon}</span><select class="left"><option>${esc(r.left)}</option><option>Precio</option><option>SMA 50</option><option>SMA 200</option><option>RSI</option><option>MACD</option><option>Pérdida</option><option>Ganancia</option></select><select class="op"><option>${esc(r.op)}</option><option>cruza por encima</option><option>cruza por debajo</option><option>es mayor que</option><option>es menor que</option><option>alcanza</option></select><input class="value" value="${esc(r.value)}" aria-label="Valor"/><button class="remove" aria-label="Eliminar">×</button></div>`}
function render(){['entry','exit'].forEach(side=>$(`#${side}Rules`).innerHTML=state[side].map((r,i)=>ruleTemplate(r,side,i)).join(''));$('#indicatorCount').textContent=new Set([...state.entry,...state.exit].map(x=>x.left).filter(x=>/SMA|EMA|RSI|MACD/.test(x))).size;$('#conditionCount').textContent=state.entry.length+state.exit.length;bindRules();updateCode();save()}
function bindRules(){$$('.rule').forEach(el=>{const side=el.dataset.side,i=+el.dataset.index;el.querySelector('.remove').onclick=()=>{state[side].splice(i,1);render()};['left','op','value'].forEach(k=>el.querySelector('.'+k).onchange=e=>{state[side][i][k]=e.target.value;updateCode();save()})})}
function addRule(side,type='greater'){state[side].push({...presets[type]});render()}
function pyName(){return ($('#strategyName').value||'Visual Strategy').replace(/[^a-zA-Z0-9 ]/g,'').split(/\s+/).map(s=>s[0]?.toUpperCase()+s.slice(1)).join('')||'VisualStrategy'}
function ruleExpr(r){const n=parseFloat(r.value)||0,l=r.left||'',o=r.op||'';if(l==='Pérdida')return `price <= self.entry_price * (1 - ${n/100})`;if(l==='Ganancia')return `price >= self.entry_price * (1 + ${n/100})`;if(l==='RSI')return `self.rsi[0] ${o.includes('menor')?'<':'>'} ${n}`;if(l==='Precio')return `price ${o.includes('menor')?'<':'>'} self.slow_sma[0]`;if(l==='MACD')return `self.macd.macd[0] ${o.includes('debajo')||o.includes('menor')?'<':'>'} self.macd.signal[0]`;return `self.cross ${o.includes('debajo')?'<':'>'} 0`}
function generateCode(){const name=pyName(),cash=+$('#cash').value||10000,comm=(+$('#commission').value||0)/100,size=Math.min(100,Math.max(1,+$('#size').value||95)),entry=state.entry.map(ruleExpr).join(' and ')||'False',exit=state.exit.map(ruleExpr).join(' or ')||'False';return `"""Generated by Strategy Backtest Studio.\nAttach your own Backtrader data feed before running.\n"""\nimport backtrader as bt\n\n\nclass ${name}(bt.Strategy):\n    params = dict(fast_period=50, slow_period=200, rsi_period=14)\n\n    def __init__(self):\n        self.fast_sma = bt.indicators.SMA(self.data.close, period=self.p.fast_period)\n        self.slow_sma = bt.indicators.SMA(self.data.close, period=self.p.slow_period)\n        self.rsi = bt.indicators.RSI(self.data.close, period=self.p.rsi_period)\n        self.macd = bt.indicators.MACD(self.data.close)\n        self.cross = bt.indicators.CrossOver(self.fast_sma, self.slow_sma)\n        self.entry_price, self.order = None, None\n\n    def notify_order(self, order):\n        if order.status in [order.Submitted, order.Accepted]:\n            return\n        if order.status == order.Completed and order.isbuy():\n            self.entry_price = order.executed.price\n        self.order = None\n\n    def next(self):\n        if self.order:\n            return\n        price = self.data.close[0]\n        if not self.position:\n            # Entrada: todas las condiciones visuales deben cumplirse\n            if ${entry}:\n                quantity = (self.broker.getcash() * ${size/100}) / price\n                self.order = self.buy(size=quantity)\n        else:\n            # Salida: cualquiera de las condiciones puede cerrar\n            if ${exit}:\n                self.order = self.close()\n\n\ndef build_cerebro():\n    cerebro = bt.Cerebro(stdstats=True)\n    cerebro.addstrategy(${name})\n    cerebro.broker.setcash(${cash}.0)\n    cerebro.broker.setcommission(commission=${comm.toFixed(4)})\n    cerebro.addanalyzer(bt.analyzers.SharpeRatio, _name='sharpe')\n    cerebro.addanalyzer(bt.analyzers.DrawDown, _name='drawdown')\n    cerebro.addanalyzer(bt.analyzers.TradeAnalyzer, _name='trades')\n    return cerebro\n\n\nif __name__ == '__main__':\n    cerebro = build_cerebro()\n    # TODO: cerebro.adddata(your_data_feed)\n    if not cerebro.datas:\n        raise RuntimeError('Agregá un data feed antes de ejecutar el backtest.')\n    print(f'Capital inicial: {cerebro.broker.getvalue():.2f}')\n    cerebro.run()\n    print(f'Capital final: {cerebro.broker.getvalue():.2f}')\n`}
function updateCode(){const valid=state.entry.length>0&&state.exit.length>0&&+$('#cash').value>0&&+$('#size').value>0;$('#codePreview').textContent=generateCode();$('#riskSummary').textContent=((+$('#commission').value||0)+(+state.exit.find(x=>x.left==='Pérdida')?.value||2)).toFixed(1)+'%';$('#validationStatus').classList.toggle('invalid',!valid);$('#validationStatus').innerHTML=`<i></i> ${valid?'Estrategia válida':'Revisar estrategia'}`;const checks=[state.entry.length>0,state.exit.length>0,state.exit.some(x=>x.left==='Pérdida'||x.left==='Ganancia'),+$('#cash').value>0&&+$('#size').value>0];$('#preflightCount').textContent=checks.filter(Boolean).length+'/4'}
function downloadText(text,type,name){const blob=new Blob([text],{type}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();URL.revokeObjectURL(a.href)}
function download(){downloadText(generateCode(),'text/x-python',pyName()+'.py');toast('Estrategia Python exportada')}
function toast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),1800)}
function save(){localStorage.setItem('sbs-strategy',JSON.stringify({state,name:$('#strategyName').value,cash:$('#cash').value,commission:$('#commission').value,size:$('#size').value,timeframe:$('#timeframe').value}));$('#saveState').textContent='● Guardado'}
function load(){try{const x=JSON.parse(localStorage.getItem('sbs-strategy'));if(x){state=x.state;$('#strategyName').value=x.name;$('#cash').value=x.cash;$('#commission').value=x.commission;$('#size').value=x.size;if(x.timeframe)$('#timeframe').value=x.timeframe}}catch(e){}}
$$('.add-condition').forEach(b=>b.onclick=()=>addRule(b.dataset.side));$$('.block').forEach(b=>{b.onclick=()=>addRule(['stop','take'].includes(b.dataset.type)?'exit':'entry',b.dataset.type);b.ondragstart=e=>e.dataTransfer.setData('text/plain',b.dataset.type)});['entry','exit'].forEach(side=>{const el=$(`#${side}Rules`).parentElement;el.ondragover=e=>e.preventDefault();el.ondrop=e=>{e.preventDefault();addRule(side,e.dataTransfer.getData('text/plain'))}});
$('#blockSearch').oninput=e=>$$('.block').forEach(b=>b.style.display=b.textContent.toLowerCase().includes(e.target.value.toLowerCase())?'flex':'none');$('#codeTab').onclick=e=>{$('.canvas').classList.toggle('hidden');$('#codePanel').classList.toggle('hidden');$$('.tabs button').forEach(x=>x.classList.remove('active'));e.target.classList.add('active');updateCode()};$$('.tabs button')[0].onclick=e=>{$('.canvas').classList.remove('hidden');$('#codePanel').classList.add('hidden');$$('.tabs button').forEach(x=>x.classList.remove('active'));e.target.classList.add('active')};
$('#copyCode').onclick=async()=>{await navigator.clipboard.writeText(generateCode());toast('Código copiado')};['exportTop','exportSide'].forEach(id=>$('#'+id).onclick=download);['strategyName','cash','commission','size','timeframe'].forEach(id=>$('#'+id).oninput=()=>{updateCode();save()});$('#newStrategy').onclick=()=>{state={entry:[],exit:[]};$('#strategyName').value='Nueva estrategia';render()};$('#loadExample').onclick=()=>{state={entry:[{...presets.cross},{...presets.rsi}],exit:[{...presets.cross,op:'cruza por debajo'},{...presets.stop},{...presets.take}]};$('#strategyName').value='Cruce de medias + RSI';render()};$('#exportJson').onclick=()=>{const config={schema:'strategy-backtest-studio/v1',name:$('#strategyName').value,settings:{cash:+$('#cash').value,commission:+$('#commission').value,position_size:+$('#size').value,timeframe:$('#timeframe').value},rules:state};downloadText(JSON.stringify(config,null,2),'application/json',pyName()+'.json');toast('Configuración exportada')};
load();render();

